    INF = float('inf')
    MAX_DIAMONDS = 314000000

    def bfs(start):
        q = deque([(start, 0, 0)])
        visited = [False] * n
        visited[start] = True
        min_diamonds = INF
        max_diamonds = -INF
        cycle = False
        while q:
            node, diamonds, depth = q.popleft()
            for split in splits[node]:
                new_diamonds = diamonds
                new_monsters = []
                for x in split:
                    if x == -1:
                        new_diamonds += 1
                    else:
                        new_monsters.append(x - 1)
                if len(new_monsters) == 0:
                    min_diamonds = min(min_diamonds, new_diamonds)
                    max_diamonds = max(max_diamonds, new_diamonds)
                else:
                    for monster in new_monsters:
                        if not visited[monster]:
                            visited[monster] = True
                            q.append((monster, new_diamonds, depth + 1))
                        elif depth > 0:
                            cycle = True
        if cycle:
            return -1, -1
